function splitReqs(text){
  return String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
}
function genCases(reqs){
  reqs = splitReqs(reqs);
  var cases=[];
  reqs.forEach(function(req, i){
    var id='TC'+(i+1);
    cases.push({id:id+'-P', req:req, type:'正常流程',
      pre:'系统已登录且功能可用', step:'按预期方式操作：'+req, expect:'功能按需求正常工作，结果符合预期'});
    cases.push({id:id+'-B', req:req, type:'边界值',
      pre:'处于输入/状态边界', step:'使用边界值（最小/最大/空/临界）执行：'+req, expect:'系统在边界下行为确定、不崩溃、数据一致'});
    cases.push({id:id+'-N', req:req, type:'异常/负面',
      pre:'提供非法或异常输入', step:'以异常方式操作：'+req, expect:'系统给出明确错误提示并安全拒绝，状态不变'});
  });
  return {count:cases.length, reqCount:reqs.length, cases:cases};
}
function toMarkdown(reqs){
  var r=genCases(reqs);
  var lines=['# 测试用例','| 用例ID | 需求 | 类型 | 前置条件 | 步骤 | 预期结果 |',
             '|--------|------|------|----------|------|----------|'];
  r.cases.forEach(function(c){ lines.push('| '+c.id+' | '+c.req+' | '+c.type+' | '+c.pre+' | '+c.step+' | '+c.expect+' |'); });
  return {markdown:lines.join('\n'), count:r.count, reqCount:r.reqCount};
}
var EXPORTS={splitReqs:splitReqs, genCases:genCases, toMarkdown:toMarkdown};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TestCaseForgePure = EXPORTS; }
